from harness.assertions import assert_guarded_write, assert_refusal
from harness.docker_util import ProbeError
from stubs.fake_tree import FakeRest, FakeTree
from stubs.fake_write_shapes import BLOG_POST, BODY_NOTE, FakeWriteMcp

CHILD = "I0002"
FAMILY = "F0000"
CHILD_REF = "child_ref_list.0.ref"
BODY = "text.string"
TITLE = "title"


