    """`update_blog_post(body=…)` on a post with no note creates one, and the old gate refused
    any delta for this shape — so the tool had no legal call form at all. The delta never came
    from the tool's report in the first place; it comes from the REST snapshots around it."""
    written = assert_guarded_write(
        rest,
        mcp,
        "gramps_update_blog_post",
        {"gramps_id": BLOG_POST, "body": "Hallo"},
        expect_delta={"notes": 1},
        self_report="unguarded",
        expect_record={"notes": {BODY_NOTE: {BODY: "Hallo"}}},
    )

    assert written.added == {"notes": [BODY_NOTE]}


